/* Public choices and reproducible events. All effects use the shared stocks. */
const Society=(()=>{
const fields=['agriculture','industry','arms'],foodKeys=['people','army','research','reserve'];
const curricula={
 schools:{name:'Broad education',icon:'📚',rate:.003,learning:.8,morale:1,description:'A little of everything. +1 happiness each turn; steady research.'},
 workshops:{name:'Vocational skills',icon:'🛠',rate:.002,learning:.5,morale:-1,description:'Builders and craftspeople. +50% building work and most local project work; +25% engineering research; −1 happiness.'},
 agriculture:{name:'Agricultural science',icon:'🌾',rate:.003,learning:.7,morale:0,description:'Learn how to grow food. +15% food production; +50% irrigation project work; +25% food research.'},
 academies:{name:'Advanced scholarship',icon:'🎓',rate:.004,learning:1.2,morale:-2,description:'Intensive study. +50% research in every field; higher school costs; −2 happiness.'},
 civics:{name:'Community & citizenship',icon:'🤝',rate:.003,learning:.8,morale:2,description:'Practice working together. +2 happiness each turn; research is 10% slower.'},
 military:{name:'Military training',icon:'🛡',rate:.003,learning:.6,morale:-1,description:'Prepare recruits. +2 readiness for fed regiments each turn; +25% equipment research; −1 happiness.'}
};
const laws={
 service:{name:'Military service',options:{voluntary:{name:'Voluntary service',icon:'🕊',description:'Military recruits normally. No extra cost or happiness change.',morale:0,unrest:0},conscription:{name:'Conscription',icon:'🛡',description:'Draft 10 residents per turn: 10 money, 4 metal, 2 cloth and 10 military allowance. −3 happiness and +6 unrest pressure each turn, even if recruitment stalls.',morale:-3,unrest:6}}},
 work:{name:'Working conditions',options:{balanced:{name:'Regular workday',icon:'⚖',description:'Normal output and no happiness change.',morale:0,unrest:0},overtime:{name:'Longer workdays',icon:'⚒',description:'+15% money, wood, metal and cloth production. −2 happiness and +4 unrest pressure each turn.',morale:-2,unrest:4},protections:{name:'Worker protections',icon:'🏡',description:'−10% money, wood, metal and cloth production. +2 happiness and −4 unrest pressure each turn.',morale:2,unrest:-4}}},
 care:{name:'Community support',options:{none:{name:'Local self-help',icon:'🏘',description:'No extra national cost or happiness change.',morale:0,unrest:0},kitchens:{name:'Community kitchens',icon:'🍲',description:'+3 happiness and −4 unrest pressure when fully funded. Costs 5 money plus 1 food per 550 residents, rounded up, from the people allocation.',morale:3,unrest:-4}}}
};
const rations={lean:{name:'Small portions',amount:.8,morale:-2},normal:{name:'Regular portions',amount:1,morale:0},generous:{name:'Generous portions',amount:1.2,morale:2}};
const clamp=(n,a=0,b=100)=>Math.max(a,Math.min(b,n));
function check(ok,msg){if(!ok)throw Error(msg);}
function shares(value,keys){return value&&Object.keys(value).length===keys.length&&keys.every(k=>Number.isInteger(value[k])&&value[k]>=0&&value[k]<=100)&&keys.reduce((n,k)=>n+value[k],0)===100;}
function upgrade(s){s.release='0.9.0';s.events=s.events??[];for(const c of s.countries){c.foodShares=c.foodShares??{people:65,army:20,research:10,reserve:5};c.rations=c.rations??'normal';c.laws=c.laws??{service:'voluntary',work:'balanced',care:'none'};c.unrest=c.unrest??10;c.eventsTurn=c.eventsTurn??0;}return s;}
function setFood(s,id,values,ration){check(s.phase==='implement','Plan food during Implement.');check(shares(values,foodKeys)&&Object.hasOwn(rations,ration),'Food shares must be whole percentages totaling 100.');s.countries[id].foodShares={...values};s.countries[id].rations=ration;}
function setSchool(s,id,key){check(s.phase==='implement','Choose school subjects during Implement.');check(Object.hasOwn(curricula,key),'Choose a school curriculum.');s.countries[id].education=key;}
function setLaw(s,id,group,key){check(s.phase==='implement','Choose laws during Implement.');check(Object.hasOwn(laws,group)&&Object.hasOwn(laws[group].options,key),'Choose a listed law.');s.countries[id].laws[group]=key;}
function researchRate(c,field){return c.education==='academies'?1.5:c.education==='civics'?.9:({workshops:'industry',agriculture:'agriculture',military:'arms'}[c.education]===field?1.25:1);}
function outputRate(c,good){const work=c.laws?.work,industry=['money','wood','metal','cloth'].includes(good);return (industry?(work==='overtime'?1.15:work==='protections'?.9:1):1)*(good==='food'&&c.education==='agriculture'?1.15:1);}
function workRate(c,type,local=false){return c&&(c.education==='workshops'&&(!local||['mining','forestry','weaving','housing'].includes(type))||c.education==='agriculture'&&local&&type==='farming')?1.5:1;}
function civilianNeed(s,c){return s.cells.filter(x=>x.country===c.id).reduce((n,x)=>n+x.population,0)/110*rations[c.rations].amount;}
function kitchenCost(s,c){return Math.ceil(s.cells.filter(x=>x.country===c.id).reduce((n,x)=>n+x.population,0)/550);}
function armyRequest(s,c){return s.regiments.filter(r=>r.country===c.id&&r.troops>0&&Military.connected(s,r,Game.relation)).reduce((n,r)=>n+Math.min(Math.max(0,Math.max(10,r.troops*.8)-r.supply),Math.ceil(r.troops*.1)*2),0);}
function foodPlan(s,c,available=c.stock.food+Game.totals(s,c.id).food){return {available,limits:Object.fromEntries(foodKeys.map(k=>[k,available*c.foodShares[k]/100])),needs:{people:civilianNeed(s,c)+(c.laws.care==='kitchens'?kitchenCost(s,c):0),army:armyRequest(s,c),research:Research.kit(c,c.funding).food||0}};}
function distribute(s,c){const plan=foodPlan(s,c,c.stock.food),need=civilianNeed(s,c),fed=Math.min(need,plan.limits.people,c.stock.food);c.stock.food-=fed;c.foodReport={turn:s.turn,...plan,used:{people:fed,army:0,research:0,reserve:0},civilianNeed:need,civilianFed:fed};return fed+1e-8<need;}
function draftReason(s,c){if(c.militaryBudget<10)return 'needs 10 military allowance';if(c.stock.money<10||c.stock.metal<4||c.stock.cloth<2)return 'needs 10 money, 4 metal and 2 cloth';if(!s.cells.some(x=>x.country===c.id&&Civic.settlement(x)&&x.population>=35))return 'needs a home settlement with at least 35 residents';if(s.regiments.length>=5000&&!s.regiments.some(r=>r.country===c.id&&s.cells[r.cell].country===c.id&&Civic.settlement(s.cells[r.cell])&&s.cells[r.cell].population>=35))return 'regiment limit reached';return '';}
function draft(s,c,notes){const reason=draftReason(s,c);if(reason){notes.push(`${c.name}: conscription stalled — ${reason}.`);return 0;}const eligible=s.regiments.filter(r=>r.country===c.id&&s.cells[r.cell].country===c.id&&Civic.settlement(s.cells[r.cell])&&s.cells[r.cell].population>=35).sort((a,b)=>a.id-b.id);let r=eligible.find(r=>r.id===c.draftRegiment)||eligible[0];const cell=r?s.cells[r.cell]:s.cells.filter(x=>x.country===c.id&&Civic.settlement(x)&&x.population>=35).sort((a,b)=>b.population-a.population||a.id-b.id)[0];if(!r){r={id:s.nextId++,name:c.name+' Reserve',country:c.id,cell:cell.id,troops:0,units:{infantry:0,archers:0,cavalry:0,artillery:0},supply:0,readiness:60,order:null,stance:'defend',target:null,supplyStatus:'New recruits'};s.regiments.push(r);}r.readiness=(r.readiness*r.troops+600)/(r.troops+10);r.units.infantry+=10;r.troops+=10;cell.population-=10;c.stock.money-=10;c.stock.metal-=4;c.stock.cloth-=2;c.militaryBudget-=10;notes.push(`${c.name}: 10 residents joined ${r.name}; conscription used 10 money, 4 metal and 2 cloth. Workers become soldiers; they still need food.`);return 10;}
function policies(s,c,shortage,notes){const before=c.morale,oldUnrest=c.unrest,report=c.foodReport;let morale=curricula[c.education].morale+({balanced:0,taxation:-3,relief:3}[c.economy]),pressure=0;const coverage=report.civilianNeed?report.civilianFed/report.civilianNeed:1;morale+=coverage>=1-1e-8?rations[c.rations].morale:0;if(shortage)morale-=8;for(const [group,key]of Object.entries(c.laws)){const law=laws[group].options[key];if(group==='care'&&key==='kitchens'){const food=kitchenCost(s,c);if(c.stock.money<5||c.stock.food<food||report.limits.people-report.used.people+1e-8<food){notes.push(`${c.name}: community kitchens paused — need 5 money and ${food} food in the people allocation.`);continue;}c.stock.money-=5;c.stock.food-=food;report.used.people+=food;}morale+=law.morale;pressure+=law.unrest;}if(c.laws.service==='conscription')draft(s,c,notes);c.morale=clamp(c.morale+morale,10,100);c.unrest=clamp(c.unrest+clamp((60-c.morale)/10+pressure+(shortage?8:0),-6,12));c.policyReport={turn:s.turn,moraleBefore:before,moraleAfter:c.morale,unrestBefore:oldUnrest,unrestAfter:c.unrest};notes.push(`${c.name}: food to people ${report.civilianFed.toFixed(1)}/${report.civilianNeed.toFixed(1)}; happiness ${before.toFixed(0)} → ${c.morale.toFixed(0)}, unrest ${oldUnrest.toFixed(0)} → ${c.unrest.toFixed(0)}.${shortage?' Food or upkeep shortage: −8 happiness.':''}`);}
// Stable per country, turn and category; refreshing a save never rerolls a turn.
function roll(s,c,channel){let h=2166136261;for(const ch of `${s.seed}:${s.turn}:${c.id}:${channel}`){h^=ch.charCodeAt(0);h=Math.imul(h,16777619);}h^=h>>>16;h=Math.imul(h,0x7feb352d);h^=h>>>15;h=Math.imul(h,0x846ca68b);h^=h>>>16;return (h>>>0)/4294967296;}
function risk(c){return {negative:.04+.36*c.unrest/100,positive:.12*(1-c.unrest/150),natural:.18};}
const eventCatalog={
 harvest:{name:'Helpful rains',icon:'🌦',kind:'natural',tone:'positive'},breeze:{name:'Clear working weather',icon:'☀',kind:'natural',tone:'positive'},drought:{name:'Dry spell',icon:'🌵',kind:'natural',tone:'negative'},storm:{name:'Storm repairs',icon:'🌧',kind:'natural',tone:'negative'},
 festival:{name:'Community festival',icon:'🎉',kind:'social',tone:'positive'},volunteers:{name:'Neighbors pitch in',icon:'🤝',kind:'social',tone:'positive'},protest:{name:'Public protest',icon:'📣',kind:'social',tone:'negative'},strike:{name:'Work stoppage',icon:'✋',kind:'social',tone:'negative'}
};
function eventChoices(s,c){const list=[],chances=risk(c),weather=roll(s,c,'nature'),social=roll(s,c,'society');if(weather<chances.natural)list.push(['harvest','breeze','drought','storm'][Math.floor(roll(s,c,'weather-kind')*4)]);if(social<chances.negative)list.push(roll(s,c,'social-kind')<.5?'protest':'strike');else if(social<chances.negative+chances.positive)list.push(roll(s,c,'social-kind')<.5?'festival':'volunteers');return list;}
function events(s,notes){for(const c of s.countries){if(c.eventsTurn===s.turn)continue;c.eventsTurn=s.turn;for(const key of eventChoices(s,c)){const definition=eventCatalog[key],effects={};function good(k,n){const change=n<0?-Math.min(c.stock[k],-n):n;c.stock[k]+=change;effects[k]=change;}function mood(n){const before=c.morale;c.morale=clamp(c.morale+n,10,100);effects.happiness=c.morale-before;}if(key==='harvest')good('food',Math.max(5,Math.min(30,Game.totals(s,c.id).food*.2)));if(key==='breeze')good('wood',10);if(key==='drought')good('food',-Math.min(30,c.stock.food*.1));if(key==='storm')good('wood',-Math.min(20,c.stock.wood*.1));if(key==='festival'){mood(3);c.unrest=clamp(c.unrest-4);}if(key==='volunteers'){good('wood',5);good('cloth',5);}if(key==='protest'){good('money',-Math.min(30,c.stock.money*.08));mood(-2);c.unrest=clamp(c.unrest+3);}if(key==='strike'){for(const k of ['wood','metal','cloth'])good(k,-Math.min(10,c.stock[k]*.06));mood(-1);}const text=Object.entries(effects).map(([k,n])=>`${n>=0?'+':''}${n.toFixed(1)} ${k}`).join(', ');s.events.unshift({key,country:c.id,turn:s.turn,effects});notes.push(`${c.name}: ${definition.icon} ${definition.name} (${definition.kind}) — ${text}.`);}}s.events=s.events.slice(0,120);}
function validate(s){check(Array.isArray(s.events)&&s.events.length<=120&&s.events.every(e=>Object.hasOwn(eventCatalog,e.key)&&Number.isInteger(e.country)&&s.countries[e.country]&&Number.isInteger(e.turn)&&e.turn>0&&e.turn<=s.turn&&e.effects&&Object.entries(e.effects).every(([k,n])=>['food','wood','metal','cloth','money','happiness'].includes(k)&&Number.isFinite(n)&&Math.abs(n)<=1e12)),'Invalid world event record.');for(const c of s.countries){check(shares(c.foodShares,foodKeys)&&Object.hasOwn(rations,c.rations)&&Object.hasOwn(curricula,c.education),'Invalid food plan or curriculum.');check(c.laws&&Object.keys(c.laws).length===3&&Object.entries(laws).every(([k,v])=>Object.hasOwn(v.options,c.laws[k]))&&Number.isFinite(c.unrest)&&c.unrest>=0&&c.unrest<=100,'Invalid law or unrest.');check(Number.isInteger(c.eventsTurn)&&c.eventsTurn>=0&&c.eventsTurn<=s.turn,'Invalid event turn.');check(c.draftRegiment===undefined||c.draftRegiment===null||Number.isInteger(c.draftRegiment)&&c.draftRegiment>0,'Invalid draft destination.');if(c.policyReport){const p=c.policyReport;check(Number.isInteger(p.turn)&&p.turn>0&&p.turn<=s.turn&&['moraleBefore','moraleAfter','unrestBefore','unrestAfter'].every(k=>Number.isFinite(p[k])&&p[k]>=0&&p[k]<=100),'Invalid policy report.');}if(c.foodReport){const p=c.foodReport;check(Number.isInteger(p.turn)&&p.turn>0&&p.turn<=s.turn&&Number.isFinite(p.available)&&p.available>=0&&[p.limits,p.used].every(v=>v&&foodKeys.every(k=>Number.isFinite(v[k])&&v[k]>=0))&&foodKeys.every(k=>p.used[k]<=p.limits[k]+1e-6)&&Number.isFinite(p.civilianNeed)&&Number.isFinite(p.civilianFed)&&p.civilianFed>=0&&p.civilianFed<=p.civilianNeed+1e-6,'Invalid food report.');}}}
return {curricula,laws,rations,foodKeys,shares,upgrade,setFood,setSchool,setLaw,researchRate,outputRate,workRate,civilianNeed,kitchenCost,armyRequest,foodPlan,distribute,draftReason,draft,policies,risk,roll,eventCatalog,eventChoices,events,validate};})();
